"use client";

/**
 * `<ChatMessage>` — render a chat turn from a `UIMessage` (Vercel AI SDK
 * `parts: UIMessagePart[]` shape).
 *
 * Forked structural shell from `vercel/ai-elements` `<Message>` +
 * `<MessageContent>` (Apache-2.0, see NOTICE). The role-discriminated
 * styling (user-aligned right with secondary bubble, assistant-aligned
 * left with primary accent border) preserves TheoUI's Violet Forge look.
 *
 * Two consumption shapes:
 *
 *   1. **Convenience** — pass a full `UIMessage`, parts are dispatched to
 *      their built-in renderers automatically:
 *
 *        <ChatMessage message={msg} />
 *
 *   2. **Composable** — render children explicitly when you need to
 *      compose actions/branching/custom parts:
 *
 *        <ChatMessage.Root from="assistant">
 *          <ChatMessage.Content>
 *            <ChatMessageResponse text="Hello **world**" />
 *          </ChatMessage.Content>
 *          <ChatMessageToolbar>
 *            <ChatMessageActions>
 *              <ChatMessageAction tooltip="Copy"><CopyIcon /></ChatMessageAction>
 *            </ChatMessageActions>
 *          </ChatMessageToolbar>
 *        </ChatMessage.Root>
 */
import type { HTMLAttributes, ReactNode } from "react";
import { forwardRef } from "react";
import { cn } from "@/lib/cn";
import {
  type DataUIPart,
  type FileUIPart,
  type MessageRole,
  type ReasoningFileUIPart,
  type ReasoningUIPart,
  type SourceDocumentUIPart,
  type SourceUrlUIPart,
  type TextUIPart,
  type ToolUIPart,
  type UIMessage,
  type UIMessagePart,
  isDataUIPart,
  isFileUIPart,
  isReasoningFileUIPart,
  isReasoningUIPart,
  isSourceDocumentUIPart,
  isSourceUrlUIPart,
  isStepStartUIPart,
  isTextUIPart,
  isToolUIPart,
} from "@/types/chat";
import {
  AgentToolRenderer,
  type ClassifyTool,
  type ToolRendererRegistry,
} from "@/components/ui/agent-tool-renderer/agent-tool-renderer";
import { DataPart, type DataRendererMap } from "@/components/ui/chat-message/parts/data-part";
import { FilePart } from "@/components/ui/chat-message/parts/file-part";
import { ReasoningPart } from "@/components/ui/chat-message/parts/reasoning-part";
import { SourceDocumentPart, SourceUrlPart } from "@/components/ui/chat-message/parts/source-part";
import { TextPart } from "@/components/ui/chat-message/parts/text-part";

/* ─── <ChatMessage.Root> ─────────────────────────────────────────────── */

export type ChatMessageRootProps = HTMLAttributes<HTMLDivElement> & {
  /** Sender role — controls layout (right-aligned bubble for `user`, left for `assistant`/`system`). */
  from: MessageRole;
};

export const ChatMessageRoot = forwardRef<HTMLDivElement, ChatMessageRootProps>(
  ({ className, from, children, ...props }, ref) => (
    <div
      data-slot="chat-message-root"
      ref={ref}
      className={cn(
        "group flex w-full max-w-[95%] flex-col gap-2",
        from === "user"
          ? "is-user ml-auto justify-end"
          : from === "assistant"
            ? "is-assistant"
            : "is-system",
        className,
      )}
      data-theo-chat-message={from}
      {...props}
    >
      {children}
    </div>
  ),
);
ChatMessageRoot.displayName = "ChatMessageRoot";

/* ─── <ChatMessage.Content> ──────────────────────────────────────────── */

export type ChatMessageContentVariant = "contained" | "flat";

export interface ChatMessageContentProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * `contained` (default) — bubble surface (background + padding + radius).
   * Applied to user role automatically. Assistant defaults to `flat`.
   *
   * `flat` — no bubble, content flows directly. Use for assistant or system.
   */
  variant?: ChatMessageContentVariant;
}

export const ChatMessageContent = forwardRef<HTMLDivElement, ChatMessageContentProps>(
  ({ className, variant, children, ...props }, ref) => (
    <div
      data-slot="chat-message-content"
      ref={ref}
      className={cn(
        "flex w-fit min-w-0 max-w-full flex-col gap-2 overflow-hidden text-body-md",
        // User bubble — secondary surface, right-aligned (within the `is-user` group)
        "group-[.is-user]:ml-auto",
        variant !== "flat" &&
          "group-[.is-user]:rounded-2xl group-[.is-user]:rounded-tr-md group-[.is-user]:border group-[.is-user]:border-border/40 group-[.is-user]:bg-secondary group-[.is-user]:px-4 group-[.is-user]:py-3",
        // Assistant card — primary accent border-left
        variant === "contained" &&
          "group-[.is-assistant]:rounded-2xl group-[.is-assistant]:rounded-tl-md group-[.is-assistant]:border group-[.is-assistant]:border-border/40 group-[.is-assistant]:border-l-2 group-[.is-assistant]:border-l-primary group-[.is-assistant]:bg-card group-[.is-assistant]:px-5 group-[.is-assistant]:py-4 group-[.is-assistant]:shadow-sm",
        // System callout — accent-deep border
        "group-[.is-system]:rounded-lg group-[.is-system]:border group-[.is-system]:border-accent-deep/40 group-[.is-system]:border-l-4 group-[.is-system]:bg-accent/10 group-[.is-system]:px-4 group-[.is-system]:py-2 group-[.is-system]:text-body-sm",
        "group-[.is-assistant]:text-foreground group-[.is-user]:text-secondary-foreground",
        className,
      )}
      data-theo-chat-content=""
      {...props}
    >
      {children}
    </div>
  ),
);
ChatMessageContent.displayName = "ChatMessageContent";

/* ─── Part dispatch ──────────────────────────────────────────────────── */

export interface RenderPartOptions {
  /** Consumer-defined renderers for `data-${name}` parts. */
  dataRenderers?: DataRendererMap;
  /** Override built-in renderers per part `type`. */
  partRenderers?: PartRendererMap;
  /** Registry of rich tool renderers keyed by classification kind (M5-3). */
  toolRenderers?: ToolRendererRegistry;
  /** Override the default tool classifier (M5-3). */
  classifyTool?: ClassifyTool;
}

export type PartRendererMap = Partial<{
  text: (part: TextUIPart) => ReactNode;
  reasoning: (part: ReasoningUIPart) => ReactNode;
  "reasoning-file": (part: ReasoningFileUIPart) => ReactNode;
  file: (part: FileUIPart) => ReactNode;
  "source-url": (part: SourceUrlUIPart) => ReactNode;
  "source-document": (part: SourceDocumentUIPart) => ReactNode;
  tool: (part: ToolUIPart) => ReactNode;
  data: (part: DataUIPart) => ReactNode;
  "step-start": () => ReactNode;
}>;

export function renderPart(part: UIMessagePart, opts: RenderPartOptions = {}): ReactNode {
  const overrides = opts.partRenderers ?? {};

  if (isTextUIPart(part)) {
    return overrides.text?.(part) ?? <TextPart part={part} />;
  }
  if (isReasoningUIPart(part)) {
    return overrides.reasoning?.(part) ?? <ReasoningPart part={part} />;
  }
  if (isReasoningFileUIPart(part)) {
    return overrides["reasoning-file"]?.(part) ?? null;
  }
  if (isFileUIPart(part)) {
    return overrides.file?.(part) ?? <FilePart part={part} />;
  }
  if (isSourceUrlUIPart(part)) {
    return overrides["source-url"]?.(part) ?? <SourceUrlPart part={part} />;
  }
  if (isSourceDocumentUIPart(part)) {
    return overrides["source-document"]?.(part) ?? <SourceDocumentPart part={part} />;
  }
  if (isToolUIPart(part)) {
    if (overrides.tool) return overrides.tool(part);
    return (
      <AgentToolRenderer
        part={part}
        toolRenderers={opts.toolRenderers}
        classifyTool={opts.classifyTool}
      />
    );
  }
  if (isDataUIPart(part)) {
    return overrides.data?.(part) ?? <DataPart part={part} renderers={opts.dataRenderers} />;
  }
  if (isStepStartUIPart(part)) {
    return (
      overrides["step-start"]?.() ?? (
        <hr className="my-3 border-border" aria-label="Step boundary" />
      )
    );
  }
  // CustomContentUIPart, or any unhandled future kind — render nothing.
  return null;
}

/* ─── <ChatMessage> convenience ──────────────────────────────────────── */

export interface ChatMessageProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /** The UI message to render. Parts are dispatched automatically. */
  message: UIMessage;
  /** Optional avatar slot rendered before assistant/system content. */
  avatar?: ReactNode;
  /** Optional toolbar (copy / regenerate / branch nav) rendered below the content. */
  actions?: ReactNode;
  /** Variant of the content bubble. */
  variant?: ChatMessageContentVariant;
  /** Override built-in part renderers. */
  partRenderers?: PartRendererMap;
  /** Renderers for `data-${name}` parts. */
  dataRenderers?: DataRendererMap;
  /** Registry of rich tool renderers keyed by classification kind (M5-3). */
  toolRenderers?: ToolRendererRegistry;
  /** Override the default tool classifier (M5-3). */
  classifyTool?: ClassifyTool;
}

export const ChatMessage = forwardRef<HTMLDivElement, ChatMessageProps>(
  (
    {
      message,
      avatar,
      actions,
      variant,
      partRenderers,
      dataRenderers,
      toolRenderers,
      classifyTool,
      className,
      ...props
    },
    ref,
  ) => {
    const inner = (
      <ChatMessageContent
        variant={variant ?? (message.role === "assistant" ? "contained" : undefined)}
      >
        {message.parts.map((part, idx) => (
          <div key={`${part.type}-${idx}`}>
            {renderPart(part, { dataRenderers, partRenderers, toolRenderers, classifyTool })}
          </div>
        ))}
        {actions}
      </ChatMessageContent>
    );

    if (message.role === "user") {
      return (
        <ChatMessageRoot
          data-slot="chat-message"
          ref={ref}
          from="user"
          className={className}
          {...props}
        >
          {inner}
          {avatar ? <div className="shrink-0">{avatar}</div> : null}
        </ChatMessageRoot>
      );
    }

    return (
      <ChatMessageRoot
        data-slot="chat-message"
        ref={ref}
        from={message.role}
        className={className}
        {...props}
      >
        {avatar ? <div className="shrink-0">{avatar}</div> : null}
        {inner}
      </ChatMessageRoot>
    );
  },
);
ChatMessage.displayName = "ChatMessage";

"use client";

/**
 * `<ChatMessageResponse>` — markdown text renderer for a chat message body.
 *
 * Wraps `parseMarkdownToReact` with React-friendly memoization. Re-renders
 * ONLY when `text` or `isStreaming` change, so streaming a long response
 * doesn't re-parse the entire conversation history per token.
 *
 * Internally swaps the default `<code>` element for `<CodeBlock>` (fenced)
 * or `<InlineCode>` (inline), per shadcn.io's AI code-block pattern, on top of
 * this package's own `a`/`img` defaults — see `MARKDOWN_COMPONENTS` below for
 * why they are spread here rather than merged inside the parser.
 *
 * Component override pattern is forked from `vercel/ai-elements`
 * `<MessageResponse>` (Apache-2.0, see NOTICE).
 */
import { memo, useEffect, useState } from "react";
import type { ReactElement, ReactNode } from "react";
import { cn } from "@/lib/cn";
import { CodeBlock } from "@/lib/markdown/code-block";
import { InlineCode } from "@/lib/markdown/inline-code";
import { parseMarkdownToReactSafe } from "@/lib/markdown/parser";
import { slideMarkdownComponents } from "../../primitives/slide/markdown-components";

export interface ChatMessageResponseProps {
  /** Raw markdown text from the model. */
  text: string;
  /**
   * True while tokens are still arriving. Enables the streaming-safe
   * preprocess pass (auto-closes incomplete `**bold`, fences, links, math).
   */
  isStreaming?: boolean;
  /** Extra className on the prose wrapper. */
  className?: string;
}

/**
 * Decide whether a hast `code` element is inline (single-backtick) or a
 * fenced block. Heuristic: presence of `language-X` className on `<code>`,
 * or being wrapped in `<pre>` (the runtime sees that as parent). We can't
 * see the parent here, so we use the className signal — fenced code from
 * mdast-util-from-markdown always carries `language-*`.
 */
function isFenced(props: Record<string, unknown>): boolean {
  const cls = props.className as unknown as string | string[] | undefined;
  if (typeof cls === "string") return cls.startsWith("language-");
  if (Array.isArray(cls))
    return cls.some((c) => typeof c === "string" && c.startsWith("language-"));
  return false;
}

function extractLanguage(props: Record<string, unknown>): string | undefined {
  const cls = props.className as unknown as string | string[] | undefined;
  const list = typeof cls === "string" ? [cls] : Array.isArray(cls) ? cls : [];
  for (const c of list) {
    if (typeof c === "string" && c.startsWith("language-")) {
      return c.slice("language-".length);
    }
  }
  return undefined;
}

function extractText(children: ReactNode): string {
  if (typeof children === "string") return children;
  if (Array.isArray(children)) return children.map(extractText).join("");
  if (
    children &&
    typeof children === "object" &&
    "props" in children &&
    (children as { props?: { children?: ReactNode } }).props
  ) {
    return extractText((children as { props: { children?: ReactNode } }).props.children);
  }
  return "";
}

const MARKDOWN_COMPONENTS: Record<string, unknown> = {
  // The package's element defaults FIRST, this surface's overrides after, so a key spelled here
  // wins. `slideMarkdownComponents` supplies `a` and `img`; `code`/`pre` below are the chat's own.
  //
  // ## Why the defaults are spread here and not merged inside `parser.ts`
  //
  // Both were measured before choosing. Merging in the parser resolves the class for every caller,
  // and the class has exactly ONE member: `parseMarkdownToReactSafe` is reachable from no published
  // subpath (106 explicit entries, no wildcard, none targeting `lib/markdown`) and this file is its
  // only caller in the tree — the slide runs its own `primitives/slide/parse.ts`. So the generality
  // buys nothing today, and it costs: a probe of that shape turned `parser.test.ts > renders links`
  // red, because that case asserts the parser's output for a caller passing NO map at all. Changing
  // what the parser does with an absent map is a wider change than this item measured, and it would
  // give the package a third answer to merge-vs-replace next to `slide.tsx`'s deliberate replace.
  //
  // Spreading here changes only the surface the item is about and leaves the parser's contract as
  // it is. If a second caller of the parser ever appears, that is when merging earns its ADR.
  //
  // The map is named for the slide because that is where it was written, not because its content is
  // slide-specific: it sets `loading`/`decoding` on an image and `rel` on an external anchor, which
  // every markdown surface in this package wants. Reused rather than copied — a second definition
  // would be two places to fix the next time a default changes.
  ...slideMarkdownComponents,
  code: (props: Record<string, unknown> & { children?: ReactNode }) => {
    if (isFenced(props)) {
      const language = extractLanguage(props);
      const code = extractText(props.children);
      return <CodeBlock code={code} language={language} />;
    }
    return <InlineCode {...props}>{props.children}</InlineCode>;
  },
  // Strip the default `<pre>` since `<CodeBlock>` ships its own wrapper.
  // Inline `<pre>` still works for raw whitespace-preserving text.
  pre: ({ children }: { children?: ReactNode }) => {
    return <>{children}</>;
  },
};

function ChatMessageResponseImpl({
  text,
  isStreaming = false,
  className,
}: ChatMessageResponseProps): ReactElement {
  const [tree, setTree] = useState<ReactElement | null>(null);

  useEffect(() => {
    let cancelled = false;
    parseMarkdownToReactSafe(text, {
      isStreaming,
      components: MARKDOWN_COMPONENTS,
    }).then((next) => {
      if (!cancelled) setTree(next);
    });
    return () => {
      cancelled = true;
    };
  }, [text, isStreaming]);

  return (
    <div
      data-slot="chat-message-response-impl"
      className={cn(
        "prose-theo max-w-none text-body-md text-foreground leading-relaxed",
        // First/last child margin reset — fork from vercel/ai-elements
        "[&>*:first-child]:mt-0 [&>*:last-child]:mb-0",
        // Heading sizes inside chat use our typescale, not browser defaults
        "[&_h1]:mt-4 [&_h1]:mb-2 [&_h1]:font-semibold [&_h1]:text-title-lg",
        "[&_h2]:mt-3 [&_h2]:mb-2 [&_h2]:font-semibold [&_h2]:text-title-md",
        "[&_h3]:mt-3 [&_h3]:mb-1.5 [&_h3]:font-semibold [&_h3]:text-body-lg",
        "[&_p]:my-2",
        "[&_ul]:my-2 [&_ul]:list-disc [&_ul]:pl-5",
        "[&_ol]:my-2 [&_ol]:list-decimal [&_ol]:pl-5",
        "[&_li]:my-0.5",
        "[&_blockquote]:my-2 [&_blockquote]:border-primary/40 [&_blockquote]:border-l-2 [&_blockquote]:pl-3 [&_blockquote]:text-muted-foreground",
        "[&_a:hover]:text-primary-deep [&_a]:text-primary [&_a]:underline",
        "[&_table]:my-3 [&_table]:w-full [&_table]:border-collapse",
        "[&_th]:border [&_th]:border-border [&_th]:bg-muted/40 [&_th]:px-3 [&_th]:py-1.5 [&_th]:text-left",
        "[&_td]:border [&_td]:border-border [&_td]:px-3 [&_td]:py-1.5",
        "[&_hr]:my-4 [&_hr]:border-border",
        className,
      )}
      data-theo-chat-response=""
    >
      {tree}
    </div>
  );
}

export const ChatMessageResponse = memo(ChatMessageResponseImpl, (prev, next) => {
  return prev.text === next.text && prev.isStreaming === next.isStreaming;
});
ChatMessageResponse.displayName = "ChatMessageResponse";

import { Button } from "@usetheo/ui";
/**
 * `<ChatMessageActions>` + `<ChatMessageAction>` — footer toolbar for a chat
 * message (copy, regenerate, thumbs up/down, share, edit, …).
 *
 * Forked from `vercel/ai-elements` `<MessageActions>` + `<MessageAction>`
 * (Apache-2.0, see NOTICE). Adapted to TheoUI primitives: `<Button>` from
 * `@theokit/ui` instead of shadcn, no Tooltip primitive yet (Vercel uses
 * one — we render the `tooltip` prop as a `title` attribute for now; a
 * proper Tooltip primitive lands in a follow-up RFC).
 */
import type { ComponentProps, HTMLAttributes, ReactNode } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

export type ChatMessageActionsProps = HTMLAttributes<HTMLDivElement>;

export function ChatMessageActions({
  className,
  children,
  ...props
}: ChatMessageActionsProps): JSX.Element {
  return (
    <div
      data-slot="chat-message-actions"
      className={cn("flex items-center gap-1", className)}
      data-theo-chat-actions=""
      {...props}
    >
      {children}
    </div>
  );
}

export type ChatMessageActionProps = ComponentProps<typeof Button> & {
  /** Tooltip text — rendered as native `title` for now. */
  tooltip?: string;
  /** Accessible label (used by screen readers when only an icon is visible). */
  label?: string;
  children?: ReactNode;
};

export function ChatMessageAction({
  tooltip,
  label,
  variant = "ghost",
  size = "icon",
  className,
  children,
  ...props
}: ChatMessageActionProps): JSX.Element {
  return (
    <Button
      data-slot="chat-message-action"
      type="button"
      variant={variant}
      size={size}
      title={tooltip}
      className={cn(className)}
      {...props}
    >
      {children}
      <span className="sr-only">{label || tooltip}</span>
    </Button>
  );
}

/**
 * `<ChatMessageToolbar>` — bottom-of-message bar holding actions + branch nav.
 * Forked from `vercel/ai-elements` `<MessageToolbar>` (Apache-2.0, NOTICE).
 */
import type { HTMLAttributes } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

export type ChatMessageToolbarProps = HTMLAttributes<HTMLDivElement>;

export function ChatMessageToolbar({
  className,
  children,
  ...props
}: ChatMessageToolbarProps): JSX.Element {
  return (
    <div
      data-slot="chat-message-toolbar"
      className={cn("mt-3 flex w-full items-center justify-between gap-3", className)}
      data-theo-chat-toolbar=""
      {...props}
    >
      {children}
    </div>
  );
}

"use client";

import { Button } from "@usetheo/ui";
/**
 * Message branching navigation — render multiple alternate responses for a
 * single conversation turn and let the user swipe between them.
 *
 * Forked from `vercel/ai-elements` `<MessageBranch*>` family (Apache-2.0,
 * see NOTICE). Adapted to TheoUI primitives — replaces shadcn `Button` +
 * `ButtonGroup` with our `<Button>` (no ButtonGroup primitive yet; rendered
 * as a plain wrapper).
 *
 * Composition:
 *
 *   <ChatMessageBranch>
 *     <ChatMessageBranchContent>
 *       <FirstResponse />
 *       <SecondResponse />
 *       <ThirdResponse />
 *     </ChatMessageBranchContent>
 *     <ChatMessageBranchSelector>
 *       <ChatMessageBranchPrevious />
 *       <ChatMessageBranchPage />
 *       <ChatMessageBranchNext />
 *     </ChatMessageBranchSelector>
 *   </ChatMessageBranch>
 */
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react";
import {
  type ComponentProps,
  type HTMLAttributes,
  type ReactElement,
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

interface MessageBranchContextValue {
  currentBranch: number;
  totalBranches: number;
  goToPrevious: () => void;
  goToNext: () => void;
  branches: ReactElement[];
  setBranches: (branches: ReactElement[]) => void;
}

const MessageBranchContext = createContext<MessageBranchContextValue | null>(null);

function useMessageBranch(): MessageBranchContextValue {
  const ctx = useContext(MessageBranchContext);
  if (!ctx) {
    throw new Error("ChatMessageBranch* components must be wrapped in <ChatMessageBranch>.");
  }
  return ctx;
}

export type ChatMessageBranchProps = HTMLAttributes<HTMLDivElement> & {
  defaultBranch?: number;
  onBranchChange?: (branchIndex: number) => void;
};

export function ChatMessageBranch({
  defaultBranch = 0,
  onBranchChange,
  className,
  ...props
}: ChatMessageBranchProps): JSX.Element {
  const [currentBranch, setCurrentBranch] = useState(defaultBranch);
  const [branches, setBranches] = useState<ReactElement[]>([]);

  const handleChange = useCallback(
    (next: number) => {
      setCurrentBranch(next);
      onBranchChange?.(next);
    },
    [onBranchChange],
  );

  const goToPrevious = useCallback(() => {
    handleChange(currentBranch > 0 ? currentBranch - 1 : branches.length - 1);
  }, [currentBranch, branches.length, handleChange]);

  const goToNext = useCallback(() => {
    handleChange(currentBranch < branches.length - 1 ? currentBranch + 1 : 0);
  }, [currentBranch, branches.length, handleChange]);

  const value = useMemo<MessageBranchContextValue>(
    () => ({
      branches,
      currentBranch,
      goToNext,
      goToPrevious,
      setBranches,
      totalBranches: branches.length,
    }),
    [branches, currentBranch, goToNext, goToPrevious],
  );

  return (
    <MessageBranchContext.Provider data-slot="chat-message-branch" value={value}>
      <div className={cn("grid w-full gap-2", className)} {...props} />
    </MessageBranchContext.Provider>
  );
}

export type ChatMessageBranchContentProps = HTMLAttributes<HTMLDivElement>;

export function ChatMessageBranchContent({
  children,
  ...props
}: ChatMessageBranchContentProps): JSX.Element {
  const { currentBranch, setBranches, branches } = useMessageBranch();
  const childrenArray = useMemo(
    () => (Array.isArray(children) ? (children as ReactElement[]) : [children as ReactElement]),
    [children],
  );

  useEffect(() => {
    if (branches.length !== childrenArray.length) {
      setBranches(childrenArray);
    }
  }, [childrenArray, branches, setBranches]);

  return (
    <>
      {childrenArray.map((branch, idx) => (
        <div
          className={cn("grid gap-2 overflow-hidden", idx === currentBranch ? "block" : "hidden")}
          key={
            // Prefer a stable element key; fall back to index
            (branch as ReactElement)?.key ?? `branch-${idx}`
          }
          {...props}
        >
          {branch}
        </div>
      ))}
    </>
  );
}

export type ChatMessageBranchSelectorProps = HTMLAttributes<HTMLDivElement>;

export function ChatMessageBranchSelector({
  className,
  ...props
}: ChatMessageBranchSelectorProps): JSX.Element | null {
  const { totalBranches } = useMessageBranch();
  if (totalBranches <= 1) return null;
  return (
    <div
      className={cn("inline-flex items-center gap-0.5 rounded-md border border-border", className)}
      role="group"
