/**
 * Markdown → React pipeline for chat messages.
 *
 *   parseMarkdownToReact(md, opts)
 *     ├─ preprocessStreaming(md, isStreaming)  → auto-close incomplete tokens
 *     ├─ parseBody(md)                         → mdast Root (micromark + GFM)
 *     ├─ mdastToHast(mdastTree)                → hast Root (allowDangerousHtml=false)
 *     ├─ sanitizeHast(hastTree)                → hast Root via hast-util-sanitize
 *     └─ hastToReact(hastTree)                 → React tree (jsx-runtime)
 *
 * Every transform lazily imports its peer-dep so the barrel never vendors the
 * markdown stack. Consumers that install the optional peer-deps (already
 * declared by the Slide engine) get rich rendering; consumers that don't get
 * a plain-text fallback via `parseMarkdownToReactSafe`.
 */
import type { Root as HastRoot } from "hast";
import type { Root as MdastRoot } from "mdast";
import { type ReactElement, createElement } from "react";
import { preprocessStreaming } from "@/lib/markdown/streaming-preprocess";

export interface ParseMarkdownOptions {
  /**
   * Override individual element renderers. The `components` map is passed
   * through to `hast-util-to-jsx-runtime` (e.g. `{ code: MyCodeBlock }`).
   */
  components?: Record<string, unknown>;
  /**
   * True while tokens are still arriving from the model. Enables the
   * streaming-safe preprocess pass. Default: `false`.
   */
  isStreaming?: boolean;
}

export async function parseBody(body: string): Promise<MdastRoot> {
  const [{ fromMarkdown }, { gfmFromMarkdown }, { gfm }] = await Promise.all([
    import("mdast-util-from-markdown"),
    import("mdast-util-gfm"),
    import("micromark-extension-gfm"),
  ]);
  return fromMarkdown(body, {
    extensions: [gfm()],
    mdastExtensions: [gfmFromMarkdown()],
  });
}

export async function mdastToHast(tree: MdastRoot): Promise<HastRoot> {
  const { toHast } = await import("mdast-util-to-hast");
  const hast = toHast(tree, { allowDangerousHtml: false });
  if (!hast || hast.type !== "root") {
    return { type: "root", children: hast ? [hast] : [] } as HastRoot;
  }
  return hast as HastRoot;
}

export async function sanitizeHast(tree: HastRoot): Promise<HastRoot> {
  const { sanitize, defaultSchema } = await import("hast-util-sanitize");
  // Allow class names on `pre`/`code` so syntax-highlight passes survive.
  // `defaultSchema.attributes` uses a wider union than hast-util-sanitize's
  // PropertyDefinition; cast to satisfy the parameter type while preserving
  // the same runtime shape `defaultSchema` already uses.
  const schema = {
    ...defaultSchema,
    attributes: {
      ...(defaultSchema.attributes ?? {}),
      code: [...(defaultSchema.attributes?.code ?? []), ["className", /^language-./]],
      pre: [...(defaultSchema.attributes?.pre ?? []), ["className", /./]],
      span: [...(defaultSchema.attributes?.span ?? []), ["className", /./], ["style"]],
    },
  } as Parameters<typeof sanitize>[1];
  const safe = sanitize(tree, schema);
  return safe.type === "root"
    ? (safe as HastRoot)
    : ({ type: "root", children: [safe] } as HastRoot);
}

export async function hastToReact(
  tree: HastRoot,
  components?: Record<string, unknown>,
): Promise<ReactElement> {
  const { Fragment, jsx, jsxs } = await import("react/jsx-runtime");
  const { toJsxRuntime } = await import("hast-util-to-jsx-runtime");
  return toJsxRuntime(tree, {
    Fragment,
    jsx,
    jsxs,
    // `components` is `Record<string, unknown>` on our public surface and
    // `Partial<Components>` here. It cannot be typed as the latter: `hast-util-to-jsx-runtime`
    // is an OPTIONAL peer, so naming its types in our published API would make them a hard
    // requirement for every consumer, including the ones who never render markdown. Under
    // React 18's types the two were structurally compatible and this went unnoticed; React
    // 19 tightened the value union and they no longer are. The cast is the adapter at that
    // boundary — the runtime contract is unchanged, and toJsxRuntime validates what it gets.
    components: components as Parameters<typeof toJsxRuntime>[1]["components"],
  }) as ReactElement;
}

/**
 * Public entry point. Returns a Promise<ReactElement> ready to render inline.
 * If any peer-dep is missing at runtime, the function rejects — callers
 * should use `parseMarkdownToReactSafe` for a graceful fallback.
 */
export async function parseMarkdownToReact(
  markdown: string,
  opts: ParseMarkdownOptions = {},
): Promise<ReactElement> {
  const preprocessed = preprocessStreaming(markdown, opts.isStreaming ?? false);
  const mdast = await parseBody(preprocessed);
  const hast = await mdastToHast(mdast);
  const safe = await sanitizeHast(hast);
  return hastToReact(safe, opts.components);
}

/**
 * Same as `parseMarkdownToReact` but returns a plain-text `<span>` fallback
 * if any peer-dep is missing (instead of rejecting). Used by `<ChatMessage>`
 * to keep the surface rendering when consumers opted out of the markdown
 * stack.
 */
export async function parseMarkdownToReactSafe(
  markdown: string,
  opts: ParseMarkdownOptions = {},
): Promise<ReactElement> {
  try {
    return await parseMarkdownToReact(markdown, opts);
  } catch {
    return createElement("span", { className: "whitespace-pre-wrap" }, markdown);
  }
}

/**
 * Streaming-safe markdown preprocessor.
 *
 * When markdown arrives token-by-token from an LLM, the tail of the buffer
 * is almost always mid-token: `**bold` (unclosed), `[link` (no `]`), an
 * unterminated ` ```fence`, an unfinished `$math$`. A vanilla markdown
 * parser treats those as literal text — the user sees `**bold` instead of
 * **bold** for the few hundred ms until the matching token arrives. This
 * "flash" is the single biggest UX defect of naïve streaming markdown
 * (cf. Streamdown's design note).
 *
 * The trick — adopted from Streamdown (MIT, vercel) and re-implemented
 * here — is to NEVER mutate the original buffer (the model's authoritative
 * stream), but to feed a TRANSIENTLY auto-closed copy to the parser. When
 * the next token actually closes the syntax, the temporary close was a
 * no-op and the real one takes over.
 *
 * Scope:
 *   - bold/italic markers: `**`, `__`, `*`, `_`
 *   - inline code: single backtick `` ` ``
 *   - fenced code: triple-backtick (with optional language)
 *   - inline math: `$` … `$`
 *   - block math: `$$` … `$$`
 *   - links: `[text](url)` — close the `)` if missing
 *
 * Out of scope (yet):
 *   - reference-style links `[text][ref]` — rare in LLM output
 *   - HTML tags — Tailwind v4 already sanitizes downstream
 *   - tables — partial tables render OK as plain text mid-stream
 */

/**
 * Auto-close incomplete markdown tokens in the tail of a streaming buffer.
 * Returns a copy that's safe to pass to the parser; the original buffer
 * stays untouched.
 *
 * `isStreaming = false` short-circuits (returns input unchanged) — the
 * close-tokens are only synthesized while content is still arriving.
 */
export function preprocessStreaming(markdown: string, isStreaming = true): string {
  if (!isStreaming) return markdown;

  let buf = markdown;

  /* ─── Fenced code blocks (highest priority — they swallow everything) */
  // If there's an odd number of ``` runs, the last fence is unclosed.
  const fenceCount = countTripleBackticks(buf);
  if (fenceCount % 2 === 1) {
    // Add a newline + closing fence so the parser sees a complete block.
    buf = `${buf.endsWith("\n") ? buf : `${buf}\n`}\`\`\``;
    // Once inside an unclosed fence the rest of the rules don't apply —
    // everything is code text.
    return buf;
  }

  /* ─── Block math `$$ … $$` (also greedy) */
  const blockMathCount = countOccurrences(buf, "$$");
  if (blockMathCount % 2 === 1) {
    buf = `${buf}$$`;
    return buf;
  }

  /* ─── Inline code, single backticks */
  const inlineBackticks = countSingleBackticks(buf);
  if (inlineBackticks % 2 === 1) {
    buf = `${buf}\``;
  }

  /* ─── Inline math `$ … $` (avoid double-counting `$$`) */
  const inlineDollars = countSingleDollars(buf);
  if (inlineDollars % 2 === 1) {
    buf = `${buf}$`;
  }

  /* ─── Emphasis pairs */
  // Order matters: close longer markers before shorter (`**` before `*`).
  for (const marker of ["**", "__", "*", "_"]) {
    if (countMarker(buf, marker) % 2 === 1) {
      buf = `${buf}${marker}`;
    }
  }

  /* ─── Links: `[text](url)` — close the URL paren if missing.
   * Cheap heuristic: find the last `[` after the last `]`, and the last
   * `(` after that with no matching `)`.
   */
  buf = closeUnclosedLink(buf);

  return buf;
}

/* ─── Counting helpers (avoid regex global-state pitfalls) ───────────── */

function countTripleBackticks(s: string): number {
  let count = 0;
  let i = 0;
  while (i < s.length) {
    if (s[i] === "`" && s[i + 1] === "`" && s[i + 2] === "`") {
      count++;
      i += 3;
    } else {
      i++;
    }
  }
  return count;
}

function countSingleBackticks(s: string): number {
  // Count ` characters that are NOT part of a ``` run.
  let count = 0;
  let i = 0;
  while (i < s.length) {
    if (s[i] === "`") {
      if (s[i + 1] === "`" && s[i + 2] === "`") {
        i += 3; // skip whole triple
        continue;
      }
      count++;
    }
    i++;
  }
  return count;
}

function countOccurrences(s: string, needle: string): number {
  if (needle.length === 0) return 0;
  let count = 0;
  let i = s.indexOf(needle);
  while (i !== -1) {
    count++;
    i = s.indexOf(needle, i + needle.length);
  }
  return count;
}

function countSingleDollars(s: string): number {
  // Single `$` that is NOT part of `$$`.
  let count = 0;
  let i = 0;
  while (i < s.length) {
    if (s[i] === "$") {
      if (s[i + 1] === "$") {
        i += 2; // skip whole pair
        continue;
      }
      // also skip escaped \$
      if (i > 0 && s[i - 1] === "\\") {
        i++;
        continue;
      }
      count++;
    }
    i++;
  }
  return count;
}

function countMarker(s: string, marker: string): number {
  if (marker.length === 0) return 0;
  // For single-char markers (`*`, `_`), don't count double sequences as 2 —
  // they ARE the double marker. For double-char markers, count occurrences
  // and the single-marker pass below handles leftovers.
  if (marker.length === 1) {
    let count = 0;
    let i = 0;
    while (i < s.length) {
      if (s[i] === marker) {
        if (s[i + 1] === marker) {
          // Part of double marker — skip both.
          i += 2;
          continue;
        }
        if (i > 0 && s[i - 1] === "\\") {
          i++;
          continue;
        }
        count++;
      }
      i++;
    }
    return count;
  }
  // Multi-char marker (`**`, `__`).
  let count = 0;
  let i = 0;
  while (i <= s.length - marker.length) {
    if (s.substring(i, i + marker.length) === marker) {
      count++;
      i += marker.length;
    } else {
      i++;
    }
  }
  return count;
}

function closeUnclosedLink(s: string): string {
  // Look for the trailing structure `[…](…` with no closing `)`.
  const lastOpenParen = s.lastIndexOf("(");
  const lastCloseParen = s.lastIndexOf(")");
  if (lastOpenParen === -1 || lastOpenParen <= lastCloseParen) return s;

  // The `(` must be immediately preceded by `]` to be a link.
  if (s[lastOpenParen - 1] !== "]") return s;

  // Confirm there's a `[` before that `]`.
  const closingBracket = lastOpenParen - 1;
  const openingBracket = s.lastIndexOf("[", closingBracket - 1);
  if (openingBracket === -1) return s;

  // Close it.
  return `${s})`;
}

"use client";

/**
 * `<CodeBlock>` — fenced code block with syntax highlight + copy button.
 *
 * Lazy-loads `shiki` (peer-dep optional). If shiki is not installed, falls
 * back to a plain `<pre><code>` with the language label still visible. The
 * copy button works in both modes (clipboard API only).
 *
 * Inspired by `shadcn.io`'s AI code-block pattern:
 *   - language label top-left
 *   - copy button top-right, icon swap (Copy → Check) for ~2s after success
 *   - keyboard accessible (button is a real <button>)
 *   - SSR-safe: highlighted markup is sync-rendered when ready; before
 *     hydration, plain text shows (matches Slide's shiki plugin behavior).
 *
 * Used by `parseMarkdownToReact` via the `components.code` override.
 */
import { CheckIcon, CopyIcon } from "lucide-react";
import { useEffect, useState } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

export interface CodeBlockProps {
  /** The raw source code. Newlines preserved verbatim. */
  code: string;
  /** Language hint (`typescript`, `python`, `bash`, …). Falls through if unknown. */
  language?: string;
  /** Dual-theme map — Shiki theme names. */
  themes?: { light: string; dark: string };
  /** Extra className for the outer wrapper. */
  className?: string;
}

const DEFAULT_THEMES = { light: "github-light", dark: "github-dark" };

let cachedHighlighter: unknown = null;
let highlighterFailed = false;

async function getHighlighter(themes: { light: string; dark: string }): Promise<unknown> {
  if (cachedHighlighter) return cachedHighlighter;
  if (highlighterFailed) return null;
  try {
    const shiki = await import("shiki");
    cachedHighlighter = await shiki.createHighlighter({
      themes: [themes.light, themes.dark],
      langs: [
        "ts",
        "tsx",
        "js",
        "jsx",
        "python",
        "go",
        "rust",
        "java",
        "json",
        "yaml",
        "bash",
        "shell",
        "html",
        "css",
        "sql",
        "markdown",
      ],
    });
    return cachedHighlighter;
  } catch {
    highlighterFailed = true;
    return null;
  }
}

export function CodeBlock({ code, language, themes, className }: CodeBlockProps): JSX.Element {
  const [html, setHtml] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const effectiveThemes = themes ?? DEFAULT_THEMES;

  useEffect(() => {
    let cancelled = false;
    if (!language) return;
    getHighlighter(effectiveThemes)
      .then((hl) => {
        if (cancelled || !hl) return;
        try {
          // biome-ignore lint/suspicious/noExplicitAny: shiki Highlighter is untyped here
          const out = (hl as any).codeToHtml(code, {
            lang: language,
            themes: { light: effectiveThemes.light, dark: effectiveThemes.dark },
            defaultColor: "light",
          });
          setHtml(out);
        } catch {
          // unknown language or grammar load error — pass through plain
        }
      })
      .catch(() => {
        // peer-dep missing — silent; plain <pre><code> below renders
      });
    return () => {
      cancelled = true;
    };
  }, [code, language, effectiveThemes.light, effectiveThemes.dark, effectiveThemes]);

  const handleCopy = async (): Promise<void> => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard denied — silent */
    }
  };

  return (
    <div
      className={cn(
        "group relative my-4 overflow-hidden rounded-lg border border-border bg-muted/30",
        className,
      )}
      data-theo-code-block=""
    >
      <div className="flex items-center justify-between border-border border-b bg-muted/50 px-3 py-1.5">
        <span className="font-mono text-label-caps text-muted-foreground uppercase tracking-wider">
          {language || "text"}
        </span>
        <button
          type="button"
          onClick={handleCopy}
          className={cn(
            "inline-flex h-7 items-center gap-1.5 rounded-md px-2 text-label",
            "text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground",
            "focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring",
          )}
          aria-label={copied ? "Copied" : "Copy code"}
        >
          {copied ? (
            <>
              <CheckIcon className="size-3.5" aria-hidden="true" />
              <span>Copied</span>
            </>
          ) : (
            <>
              <CopyIcon className="size-3.5" aria-hidden="true" />
              <span>Copy</span>
            </>
          )}
        </button>
      </div>
      {html ? (
        <div
          className="[&_pre]:!bg-transparent [&_pre]:!m-0 [&_pre]:!p-0 overflow-x-auto p-3 text-code-sm"
          // biome-ignore lint/security/noDangerouslySetInnerHtml: Shiki output is sanitized HTML it produced itself; no user input flows through
          dangerouslySetInnerHTML={{ __html: html }}
        />
      ) : (
        <pre className="overflow-x-auto p-3 text-code-sm">
          <code className={language ? `language-${language}` : undefined}>{code}</code>
        </pre>
      )}
    </div>
  );
}

/**
 * `<InlineCode>` — styled inline `<code>` for markdown rendering.
