      )}
      {...props}
    >
      {children}
    </code>
  );
}

"use client";

/**
 * KaTeX math rendering — inline and block.
 *
 * `<MathInline>` for `$x + y$`, `<MathBlock>` for `$$\sum_i x_i$$`. Both
 * lazy-load `katex` (peer-dep optional). When `katex` is not installed the
 * component renders a plain `<code>` fallback so the chat surface stays
 * usable.
 *
 * Markdown integration: enable in `parseMarkdownToReact` via the
 * `components` map (`{ "math-inline": MathInline, "math-block": MathBlock }`)
 * once a math mdast extension is wired in (`mdast-util-math`, peer-dep).
 */
import { useEffect, useState } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

interface KatexLib {
  renderToString: (
    tex: string,
    opts?: { displayMode?: boolean; throwOnError?: boolean; output?: string },
  ) => string;
}

let katexCache: KatexLib | null = null;
let katexFailed = false;

async function loadKatex(): Promise<KatexLib | null> {
  if (katexCache) return katexCache;
  if (katexFailed) return null;
  try {
    const mod = (await import("katex")) as unknown as { default?: KatexLib } & KatexLib;
    // `katex` ships UMD-default; both shapes exist depending on the bundler.
    const lib = mod.default ?? mod;
    katexCache = lib;
    return katexCache;
  } catch {
    katexFailed = true;
    return null;
  }
}

interface MathProps {
  /** The TeX source string (without `$` or `$$` wrappers). */
  tex: string;
  /** Inline (true) vs display (false). */
  inline: boolean;
  className?: string;
}

function MathImpl({ tex, inline, className }: MathProps): JSX.Element {
  const [html, setHtml] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    loadKatex().then((katex) => {
      if (cancelled || !katex) return;
      try {
        const out = katex.renderToString(tex, {
          displayMode: !inline,
          throwOnError: false,
          output: "html",
        });
        setHtml(out);
      } catch {
        /* invalid TeX — leave plain fallback */
      }
    });
    return () => {
      cancelled = true;
    };
  }, [tex, inline]);

  if (!html) {
    const Tag = inline ? "code" : "pre";
    return (
      <Tag
        className={cn(
          inline
            ? "rounded bg-muted px-1.5 py-0.5 font-mono text-code-sm"
            : "my-3 overflow-x-auto rounded-lg border border-border bg-muted/30 p-3 font-mono text-code-sm",
          className,
        )}
      >
        {tex}
      </Tag>
    );
  }

  const Tag = inline ? "span" : "div";
  return (
    <Tag
      className={cn(inline ? "katex-inline" : "katex-block my-3 overflow-x-auto", className)}
      // biome-ignore lint/security/noDangerouslySetInnerHtml: KaTeX renderToString output is sanitized HTML it produced itself; only `tex` (already-sanitized markdown content) flows in
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}

export type MathInlineProps = Omit<MathProps, "inline">;
export type MathBlockProps = Omit<MathProps, "inline">;

export function MathInline(props: MathInlineProps): JSX.Element {
  return <MathImpl {...props} inline={true} />;
}

export function MathBlock(props: MathBlockProps): JSX.Element {
  return <MathImpl {...props} inline={false} />;
}

"use client";

/**
 * `<MermaidDiagram>` — Mermaid diagram renderer.
 *
 * Renders a Mermaid source code block as an inline SVG. Lazy-loads
 * `mermaid` (peer-dep optional, ~200 KB) on mount; falls back to a
 * styled `<pre>` showing the raw source when the peer-dep is missing
 * OR when parsing the diagram fails (invalid syntax).
 *
 * Security note: Mermaid v11+ initialize with `securityLevel: "strict"`
 * by default, which sanitizes HTML inside diagram labels and disables
 * `click` interactions. We re-assert that here.
 *
 * In a chat context an unverified LLM response could include a malformed
 * or hostile diagram — auto-rendering is acceptable under strict mode
 * because the produced SVG goes through Mermaid's own sanitizer first.
 */
import { useEffect, useRef, useState } from "react";
import type { JSX } from "react";
import { cn } from "@/lib/cn";

interface MermaidLib {
  initialize: (opts: { startOnLoad?: boolean; securityLevel?: string; theme?: string }) => void;
  render: (id: string, src: string) => Promise<{ svg: string }>;
}

let mermaidCache: MermaidLib | null = null;
let mermaidFailed = false;

async function loadMermaid(): Promise<MermaidLib | null> {
  if (mermaidCache) return mermaidCache;
  if (mermaidFailed) return null;
  try {
    const mod = (await import("mermaid")) as unknown as { default?: MermaidLib } & MermaidLib;
    const lib = mod.default ?? mod;
    if (!lib || typeof lib.initialize !== "function") {
      mermaidFailed = true;
      return null;
    }
    lib.initialize({
      startOnLoad: false,
      securityLevel: "strict",
      theme: "default",
    });
    mermaidCache = lib;
    return mermaidCache;
  } catch {
    mermaidFailed = true;
    return null;
  }
}

let renderCounter = 0;

export interface MermaidDiagramProps {
  /** The Mermaid source code (e.g. `flowchart TD\nA-->B`). */
  source: string;
  className?: string;
}

export function MermaidDiagram({ source, className }: MermaidDiagramProps): JSX.Element {
  const [svg, setSvg] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const idRef = useRef(`theo-mermaid-${++renderCounter}`);

  useEffect(() => {
    let cancelled = false;
    loadMermaid().then(async (mermaid) => {
      if (cancelled || !mermaid) {
        if (!cancelled) setFailed(true);
        return;
      }
      try {
        const { svg: out } = await mermaid.render(idRef.current, source);
        if (!cancelled) setSvg(out);
      } catch {
        if (!cancelled) setFailed(true);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [source]);

  if (svg) {
    return (
      <div
        className={cn("my-4 flex justify-center overflow-x-auto", className)}
        data-theo-mermaid=""
        // biome-ignore lint/security/noDangerouslySetInnerHtml: Mermaid render() output is sanitized SVG it produced itself under securityLevel="strict"; only `source` (already-sanitized markdown content) flows in
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    );
  }

  return (
    <pre
      className={cn(
        "my-4 overflow-x-auto rounded-lg border border-border bg-muted/30 p-3 text-code-sm",
        failed && "border-warning/40",
        className,
      )}
      data-theo-mermaid-fallback={failed ? "true" : "loading"}
    >
      <code className="language-mermaid">{source}</code>
    </pre>
  );
}
